css:
.log-body p { margin: 0 0 0.4em; }
.log-body p:last-child { margin-bottom: 0; }
.log-body ul, .log-body ol { margin: 0.3em 0; padding-left: 1.5em; }
.log-body pre { margin: 0.3em 0; white-space: pre-wrap; font-size: 0.9em; }
.log-mention { font-weight: 600; color: var(--log-accent); }
.log-audio { color: var(--log-muted); font-size: 0.9em; }
.pb { height: 0; }
.cu-text { margin: 0; white-space: pre-wrap; }
.log-pages { --tl-bg: var(--log-screen); --tl-ink: var(--log-ink); --tl-muted: var(--log-muted); --tl-accent: var(--log-accent); --tl-warn: var(--log-warn); --tl-rule: var(--log-rule); --tl-gut: 6.4em; }
:root[data-log-showtime="false"] .log-pages { --tl-gut: 1.4em; }
@media print {
  :root[data-log-printlight="true"] .log-pages { --tl-bg: #ffffff; --tl-ink: #141414; --tl-muted: #5c5c5c; --tl-accent: #0b6b3a; --tl-warn: #8a5a00; --tl-rule: #b5b5b5; }
}
.log-page, .log-flow { background-color: var(--tl-bg); }
.log-page-header, .log-page-footer { color: var(--tl-muted); }
.log-pages { font-family: var(--log-face); color: var(--tl-ink); }
.log-node--message { margin: 0; }
.tl { display: grid; grid-template-columns: var(--tl-gut, 6.4em) 1fr; font-size: 0.92em; line-height: 1.55; color: var(--tl-ink); }
.tl-gut { grid-column: 1; grid-row: 1; padding: 0.3em 0.9em 0 0; text-align: right; }
.tl-time { display: inline-block; width: 10.5ch; font-size: 0.7em; line-height: 1.45; color: var(--tl-muted); font-variant-numeric: tabular-nums; }
:root[data-log-showtime="false"] .tl-time { display: none; }
.tl-main { grid-column: 2; grid-row: 1; position: relative; min-width: 0; padding: 0 0 calc(var(--log-gap, 0.45) * 1em) 1.1em; border-left: 1px solid var(--tl-rule); }
.tl-main::before { content: ""; position: absolute; top: 0.48em; left: -0.32em; width: 0.58em; height: 0.58em; border-radius: 50%; background: var(--log-speaker-color, var(--tl-accent)); box-shadow: 0 0 0 2px var(--tl-bg); }
.tl-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.1em 0.6em; line-height: 1.5; }
.tl-name { font-weight: 700; color: var(--tl-accent); }
.tl-name::after { content: " ::"; font-weight: 400; color: var(--tl-muted); }
.tl-tag { padding: 0 0.4em; background: var(--tl-muted); font-size: 0.75em; letter-spacing: 0.1em; color: var(--tl-bg); }
.tl-body { color: var(--tl-ink); }
.tl-body img { display: block; max-height: 13em; margin: 0.35em 0; border: 1px solid var(--tl-rule); }
.tl-body code { color: var(--tl-accent); }
.log-merged .tl-head { display: none; }
.log-merged .tl-main::before { top: 0.62em; left: -0.2em; width: 0.34em; height: 0.34em; }
.log-continued .tl-main::before { display: none; }
.log-continued .tl-main { border-left-style: dashed; }
.tl-ooc .tl-name, .tl-ooc .tl-body { color: var(--tl-muted); }
.tl-ooc .tl-main::before { background: var(--tl-bg); border: 1px solid var(--tl-muted); }
.tl-dice .tl-tag { background: var(--tl-warn); }
.tl-dice .tl-body { color: var(--tl-warn); }
.tl-dice .tl-main::before { border-radius: 0; background: var(--tl-warn); }
.tl-bot .tl-body, .tl-bot .tl-name { color: var(--tl-muted); }
.tl-bot .tl-main::before { border-radius: 0; background: var(--tl-muted); }
.tl-narr .tl-tag { background: var(--tl-accent); }
.tl-narr .tl-main::before { background: var(--tl-accent); }
.hd { margin: 0.4em 0 0.4em var(--tl-gut, 6.4em); padding: 0.35em 0 0.35em 0.9em; border-left: 3px solid var(--tl-accent); font-size: 1em; letter-spacing: 0.08em; color: var(--tl-accent); break-after: avoid; }
.hd::before { content: "## "; color: var(--tl-muted); }
[data-log-level="1"] .hd { margin-left: 0; padding: 0.35em 0.7em; border-left: 0; background: var(--tl-accent); font-size: 1.15em; color: var(--tl-bg); }
[data-log-level="1"] .hd::before { content: "▌ "; color: var(--tl-bg); }
[data-log-level="3"] .hd::before { content: "### "; }
.tr { margin: 0 0 0 var(--tl-gut, 6.4em); padding: 0.7em 0 0.7em 1.1em; border-left: 1px dashed var(--tl-muted); text-align: var(--log-style-align, left); font-size: 0.82em; letter-spacing: 0.2em; color: var(--tl-muted); }
.tr::before { content: "» "; }
.qt { margin: 0.6em 0 0.6em var(--tl-gut, 6.4em); padding: 0.4em 0.8em; border: 1px solid var(--tl-rule); border-left: 3px solid var(--tl-accent); text-align: var(--log-style-align, left); color: var(--tl-ink); }
.qt-tag { margin-bottom: 0.2em; font-size: 0.72em; letter-spacing: 0.2em; color: var(--tl-accent); }
.log-style-italic .qt { font-style: italic; }
.pro { margin: 0 0 1.2em; border: 1px solid var(--tl-rule); }
.pro-h { margin: 0; padding: 0.2em 0.7em; background: var(--tl-rule); font-size: 0.8em; letter-spacing: 0.25em; color: var(--tl-accent); }
.pro-b { padding: 0.6em 0.8em; font-size: 0.92em; color: var(--tl-ink); }
.cv { min-height: calc(var(--log-content-height, 180mm) * 0.92); display: flex; flex-direction: column; justify-content: center; break-after: page; }
.cv-boot { margin-bottom: 1.6em; font-size: 0.75em; letter-spacing: 0.3em; color: var(--tl-muted); }
.cv-title { margin: 0 0 0.4em; font-size: 2em; line-height: 1.25; letter-spacing: 0.06em; color: var(--tl-accent); }
.cv-sub { margin: 0; color: var(--tl-ink); }
.cv-fig { margin: 1.6em 0 0; }
.cv-fig img { max-height: calc(var(--log-content-height, 180mm) * 0.4); border: 1px solid var(--tl-rule); }
.cv-prompt { margin-top: 2.4em; font-size: 0.85em; color: var(--tl-muted); }
.cv-prompt::before { content: "$ "; color: var(--tl-accent); }
.cv-cursor { display: inline-block; width: 0.55em; height: 1.1em; margin-left: 0.3em; vertical-align: -0.2em; background: var(--tl-accent); }
.ip { margin: 0.8em 0 0.8em var(--tl-gut, 6.4em); padding-left: 1.1em; border-left: 1px solid var(--tl-rule); break-inside: avoid; }
.ip img { display: block; border: 1px solid var(--tl-rule); }
.ip figcaption { margin-top: 0.35em; font-size: 0.8em; color: var(--tl-muted); }
.ip figcaption::before { content: "IMG » "; color: var(--tl-accent); }
.toc { break-after: page; }
.toc-h { margin: 0 0 0.8em; font-size: 1.1em; letter-spacing: 0.3em; color: var(--tl-accent); }
.toc-h::before { content: "$ ls "; color: var(--tl-muted); }
.toc .log-toc-item { padding: 0.15em 0; border-bottom: 1px dotted var(--tl-rule); }
.toc .log-toc-page { color: var(--tl-accent); }
.cu { margin: 0.8em 0 0.8em var(--tl-gut, 6.4em); border: 1px solid var(--tl-rule); break-inside: avoid; }
.log-style-accent .cu { border-color: var(--tl-accent); }
.cu-title { padding: 0.15em 0.6em; background: var(--tl-rule); font-size: 0.85em; color: var(--tl-accent); }
.cu-text { padding: 0.4em 0.7em; font-size: 0.92em; }
.cu-note { margin: 0; padding: 0 0.7em 0.4em; font-size: 0.8em; color: var(--tl-muted); }
.ph { width: 100%; display: flex; justify-content: space-between; gap: 1em; }
.ph-title::before { content: "LOG://"; color: var(--tl-accent); }
.pf { width: 100%; text-align: right; }
.pf-num::before { content: "[ "; }
.pf-num::after { content: " ]"; }
.tl-dm { display: inline-flex; flex-wrap: wrap; gap: 0 0.4em; max-width: 100%; padding: 0 0.45em; border: 1px dashed var(--tl-accent); font-size: 0.75em; line-height: 1.5; color: var(--tl-accent); overflow-wrap: anywhere; }
.tl-dm-k { letter-spacing: 0.1em; }
.tl-dm-k::after { content: " →"; }
.tl-dm-to { font-weight: 700; }
.log-node[data-log-whisper] .tl-main::before { background: var(--tl-bg); border: 1px dashed var(--tl-accent); }
.tl-ref { display: flex; gap: 0.5em; margin: 0.05em 0 0.15em; font-size: 0.78em; line-height: 1.45; color: var(--tl-muted); }
.tl-ref::before { content: "↳ RE"; flex: none; letter-spacing: 0.05em; }
.tl-ref-who { flex: none; max-width: 35%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 700; }
.tl-ref-text { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tl-body .log-embed { margin: 0.25em 0; padding: 0.35em 0.7em; border: 1px solid var(--tl-rule); border-left: 3px solid var(--tl-accent); }
